
class ExpertSystem:
    def __init__(self, rules, facts=None):
        # Store all rules loaded from the JSON knowledge base.
        self.rules = rules

        # Facts provided by the user.
        self.facts = set(facts) if facts else set()

        # Facts generated by the inference engine.
        self.derived_facts = set()

        # Keep track of rules that have fired.
        self.fired_rules = []

    def can_fire(self, rule):
        """
        Check whether all conditions (antecedents)
        of a rule exist in the current facts.
        """

        # Get the conditions from the rule.
        conditions = rule["if"]

        # A rule can fire only if every condition is true.
        return all(condition in self.facts for condition in conditions)

    def run(self):
        """
        Forward chaining algorithm.

        Repeatedly check all rules.
        If a rule can fire, add its conclusions as new facts.
        Stop when no new rules can fire.
        """

        # Keep running while new facts are being generated.
        changed = True

        while changed:
            changed = False

            # Check every rule in the knowledge base.
            for rule in self.rules:

                # Do not fire the same rule more than once.
                if rule in self.fired_rules:
                    continue

                # Check whether the rule's conditions are satisfied.
                if self.can_fire(rule):

                    # Record the rule that fired.
                    self.fired_rules.append(rule)

                    # Get the conclusions of this rule.
                    results = rule["then"]

                    # Add each conclusion to the fact database.
                    for result in results:

                        # Only count genuinely new facts.
                        if result not in self.facts:
                            self.facts.add(result)
                            self.derived_facts.add(result)
                            changed = True

        # Return all derived conclusions.
        return self.conclusions()

    def conclusions(self):
        """
        Collect all recommendations and specifications
        generated by the inference engine.
        """

        results = []

        for fact in sorted(self.derived_facts):

            # Separate laptop recommendations.
            if fact.startswith("recommend:"):
                results.append(fact)

            # Separate laptop specifications.
            elif fact.startswith("spec:"):
                results.append(fact)

        return results
